def fig_day():
    X=lambda h:50+(h-8)*25;Y=lambda v:170-v*0.25
    o=L(50,20,50,170)+L(50,170,300,170)+L(50,Y(500),300,Y(500),'ln dash')+TR(46,Y(500)+4,'500','t-s')+TR(46,Y(0)+4,'0','t-s')
    hs=[8+i*0.5 for i in range(21)]
    o+='<path d="M'+' L'.join(f'{X(h):.1f} {Y(dl(h)):.1f}' for h in hs)+'" class="ln"/>'
    o+='<path d="M'+' L'.join(f'{X(h):.1f} {Y(max(0,500-dl(h))):.1f}' for h in hs)+'" class="lna"/>'
    for h in (8,10,12,14,16,18):o+=T(X(h),186,str(h),'t-s')
    o+=TL(58,26,'жарықтылық, лк','t-s t-b')+TL(205,40,'күн жарығы','t-s')+TL(70,Y(430),'шам','t-s ac')+TL(130,200,'тәулік уақыты, сағ','t-s mu')
    return S(340,208,o,'Күн жарығы мен шам жарығының қосындысы')
